package com.travbook.buses.adapter.out.supplier;
import com.travbook.buses.application.port.out.BusSupplier;
import com.travbook.buses.domain.model.Bus.*;
import com.travbook.shared.domain.*;
import com.travbook.shared.adapter.out.supplier.BoundedDiscovery;
import java.time.*;
import java.util.*;
import java.nio.charset.StandardCharsets;
public final class MockBusSupplier implements BusSupplier{
 private final BoundedDiscovery calls;public MockBusSupplier(BoundedDiscovery calls){this.calls=calls;}
 public Inventory search(Criteria c,Instant now){var result=calls.collect("bus",List.of("sample-roadway","sample-nightline"),p->{if(c.origin()==City.GOA||p.equals("sample-nightline")&&c.destination()==City.AGRA)throw new IllegalStateException("Simulated provider outage");var route=c.origin()+":"+c.destination();if(!Set.of("DELHI:JAIPUR","JAIPUR:DELHI","DELHI:AGRA","AGRA:DELHI","MUMBAI:PUNE","PUNE:MUMBAI","BENGALURU:MYSURU","MYSURU:BENGALURU").contains(route))return List.<Trip>of();return List.of(trip(c,p,Type.SEATER),trip(c,p,Type.SLEEPER)).stream().filter(t->t.departureAt().isAfter(now)).toList();});return new Inventory(result.items(),result.coverage());}
 private Trip trip(Criteria c,String supplier,Type type){int variant=supplier.equals("sample-roadway")?0:1;int hour=type==Type.SEATER?18:22;var at=c.date().atTime(hour,variant*15).atZone(ZoneId.of("Asia/Kolkata")).toInstant();int duration=type==Type.SEATER?300:330;var id=UUID.nameUUIDFromBytes((supplier+":"+c.origin()+":"+c.destination()+":"+c.date()+":"+type).getBytes(StandardCharsets.UTF_8));var seats=new ArrayList<Seat>();for(int deck=0;deck<(type==Type.SLEEPER?2:1);deck++)for(int i=1;i<=(type==Type.SEATER?8:4);i++)seats.add(new Seat((deck==0?"L":"U")+i,deck==0?Deck.LOWER:Deck.UPPER,(i-1)/2+1,(i-1)%2+1,type,deck==0&&i==3?SeatStatus.OCCUPIED:deck==0&&i==4?SeatStatus.RESTRICTED:SeatStatus.AVAILABLE,deck==1?12:5,TravelMoney.inr((type==Type.SLEEPER?1000:600)+variant*100L+i*25L+deck*100L)));
 return new Trip(id,supplier,variant==0?"Sample Roadway":"Sample Nightline",c.origin(),c.destination(),at,at.plusSeconds(duration*60L),"Asia/Kolkata",duration,type,variant==0,"4."+(5-variant),List.of("Charging point","Water","Synthetic rating; no verified reviews"),"MOCK booking terms: full refund before departure minus two hours; no rescheduling. Review the final policy and price in your owned booking quote.","All-in simulated seat fares; no extra booking fee. Sample boarding: arrive 20 minutes early. Restricted seats require operator assistance; upper berths require age 12+. No real operator contact.",List.of(new Stop(c.origin()+"-CENTRE","Sample central boarding point",at),new Stop(c.origin()+"-TERMINAL","Sample terminal",at.plusSeconds(900))),List.of(new Stop(c.destination()+"-CENTRE","Sample central drop",at.plusSeconds(duration*60L)),new Stop(c.destination()+"-TERMINAL","Sample terminal drop",at.plusSeconds((duration+15)*60L))),seats,seats.stream().filter(s->s.status()==SeatStatus.AVAILABLE).map(s->s.fare()).min(Comparator.comparing(m->m.decimal())).orElseThrow());}
 public Trip fresh(Trip t,Instant now){return calls.one("bus",t.supplier(),()->{if(!t.departureAt().isAfter(now))throw new DomainFailure(DomainFailure.Code.OFFER_EXPIRED,"This simulated bus departed.");var seats=t.seats().stream().map(s->new Seat(s.id(),s.deck(),s.row(),s.column(),s.type(),s.id().equals("L6")?SeatStatus.OCCUPIED:s.status(),s.minimumAge(),s.id().equals("L2")?TravelMoney.inr(s.fare().decimal().add(new java.math.BigDecimal("50"))):s.fare())).toList();return new Trip(t.id(),t.supplier(),t.operator(),t.origin(),t.destination(),t.departureAt(),t.arrivalAt(),t.timezone(),t.durationMinutes(),t.type(),t.ac(),t.rating(),t.amenities(),t.cancellationPolicy(),t.instructions(),t.boarding(),t.dropping(),seats,t.minimumFare());});}
}
